import{_ as o,o as a,c as r,a2 as s}from"./chunks/framework.lxr64Vqo.js";const m=JSON.parse('{"title":"❓ Frequently Asked Questions (FAQ)","description":"","frontmatter":{},"headers":[],"relativePath":"faq.md","filePath":"faq.md","lastUpdated":1795112636000}'),t={name:"faq.md"};function n(i,e,d,l,c,u){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="❓-frequently-asked-questions-faq" tabindex="-1">❓ Frequently Asked Questions (FAQ) <a class="header-anchor" href="#❓-frequently-asked-questions-faq" aria-label="Permalink to &quot;❓ Frequently Asked Questions (FAQ)&quot;">​</a></h1><p>Got questions? Here are the most common questions and answers about NoxMedia.</p><hr><h3 id="does-noxmedia-download-whole-files-to-my-phone-s-storage" tabindex="-1">Does NoxMedia download whole files to my phone&#39;s storage? <a class="header-anchor" href="#does-noxmedia-download-whole-files-to-my-phone-s-storage" aria-label="Permalink to &quot;Does NoxMedia download whole files to my phone&#39;s storage?&quot;">​</a></h3><p><strong>No.</strong> NoxMedia functions as a real-time streaming bridge. When you tap play on Infuse or Stremio, NoxMedia requests stream byte chunks directly from Telegram&#39;s servers and pipes them over HTTP to your player. Your device storage is not consumed by media files.</p><hr><h3 id="is-noxmedia-completely-free" tabindex="-1">Is NoxMedia completely free? <a class="header-anchor" href="#is-noxmedia-completely-free" aria-label="Permalink to &quot;Is NoxMedia completely free?&quot;">​</a></h3><p><strong>Yes.</strong> NoxMedia is 100% free and open-source under the Apache-2.0 / MIT license. There are no subscriptions, paywalls, or premium tiers.</p><hr><h3 id="can-i-stream-outside-my-home-wi-fi-network" tabindex="-1">Can I stream outside my home Wi-Fi network? <a class="header-anchor" href="#can-i-stream-outside-my-home-wi-fi-network" aria-label="Permalink to &quot;Can I stream outside my home Wi-Fi network?&quot;">​</a></h3><p><strong>Yes!</strong> There are several ways to access your NoxMedia server while traveling:</p><ol><li><strong>Tailscale / WireGuard (Recommended)</strong>: Install Tailscale on your NoxMedia host phone and your client (iPhone, laptop). You get an encrypted, zero-config private IP (e.g., <code>http://100.x.y.z:8096</code>).</li><li><strong>Cloudflare Tunnels</strong>: Route port 8096 through a Cloudflare tunnel to your own domain name.</li><li><strong>Port Forwarding</strong>: Forward external port <code>8096</code> to your host device&#39;s local IP in your router settings.</li></ol><hr><h3 id="why-does-infuse-show-an-indexing-error-in-library-mode" tabindex="-1">Why does Infuse show an indexing error in Library Mode? <a class="header-anchor" href="#why-does-infuse-show-an-indexing-error-in-library-mode" aria-label="Permalink to &quot;Why does Infuse show an indexing error in Library Mode?&quot;">​</a></h3><p>In Infuse Settings → <strong>Library</strong>, do not add NoxMedia as a library scan folder. Because Telegram channels can contain thousands of media files, Infuse&#39;s automated recursive library crawler can exhaust network timeouts. Instead, browse through <strong>Files → NoxMedia</strong> (<strong>Direct Mode</strong>), which loads directories on-demand with <strong>0ms latency</strong>!</p><hr><h3 id="is-my-telegram-account-safe" tabindex="-1">Is my Telegram account safe? <a class="header-anchor" href="#is-my-telegram-account-safe" aria-label="Permalink to &quot;Is my Telegram account safe?&quot;">​</a></h3><p><strong>Yes.</strong> NoxMedia connects using official Telegram Client API credentials (<code>api_id</code> and <code>api_hash</code>) via standard TDLib architecture. It respects Telegram&#39;s client rate limits and does not modify channel contents.</p><hr><h3 id="what-video-and-audio-codecs-are-supported" tabindex="-1">What video and audio codecs are supported? <a class="header-anchor" href="#what-video-and-audio-codecs-are-supported" aria-label="Permalink to &quot;What video and audio codecs are supported?&quot;">​</a></h3><p>Since NoxMedia serves raw direct streams, codec support depends on your client player:</p><ul><li><strong>Infuse (Apple TV/iOS)</strong>: Plays virtually everything natively (4K HDR10, Dolby Vision, HEVC/H.265, AV1, DTS-HD MA, TrueHD Atmos, FLAC).</li><li><strong>Stremio (with ExoPlayer/VLC)</strong>: Supports all common formats on Android TV and mobile.</li><li><strong>Kodi</strong>: Plays all raw remuxes and multi-channel audio tracks.</li></ul>',22)])])}const p=o(t,[["render",n]]);export{m as __pageData,p as default};
